import{_ as t,o as a,c as i,a2 as d}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse(`{"title":"Research 0002 — Device capability candidates beyond RFC 0083's v1 slice","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/docs/research/0002-device-capability-candidates.md"},"headers":[],"relativePath":"apps/mobile/research/0002-device-capability-candidates.md","filePath":"apps/mobile/research/0002-device-capability-candidates.md"}`),o={name:"apps/mobile/research/0002-device-capability-candidates.md"};function n(s,e,r,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="research-0002-—-device-capability-candidates-beyond-rfc-0083-s-v1-slice" tabindex="-1">Research 0002 — Device capability candidates beyond RFC 0083&#39;s v1 slice <a class="header-anchor" href="#research-0002-—-device-capability-candidates-beyond-rfc-0083-s-v1-slice" aria-label="Permalink to &quot;Research 0002 — Device capability candidates beyond RFC 0083&#39;s v1 slice&quot;">​</a></h1><p><strong>Status:</strong> Open. No candidate below is scoped or committed to any release.</p><h2 id="question" tabindex="-1">Question <a class="header-anchor" href="#question" aria-label="Permalink to &quot;Question&quot;">​</a></h2><p>Sovereign RFC 0083 deliberately ships a thin v1 bridge slice (<code>haptics.impact</code>, <code>notifications.native</code>) to prove the capability-negotiation contract, not to cover the device surface. What capabilities should be added next, in what order, and what does each one actually require beyond &quot;add a registry entry&quot;?</p><p>This doc exists so capability requests (from product, from plugin authors, or from a specific plugin&#39;s needs) have one place to accumulate before they turn into epic tasks — rather than each being decided ad hoc the moment someone asks for one.</p><h2 id="candidates-identified-so-far" tabindex="-1">Candidates identified so far <a class="header-anchor" href="#candidates-identified-so-far" aria-label="Permalink to &quot;Candidates identified so far&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Web API fallback exists?</th><th>Native-only reason</th><th>Notes</th></tr></thead><tbody><tr><td>Geolocation</td><td>Yes (<code>navigator.geolocation</code>)</td><td>Background location and higher accuracy need native APIs</td><td>Web tier likely covers most plugin needs already; native tier only justified for background use — see sovereign research 0005 (trip-planning plugin) for a concrete consumer.</td></tr><tr><td>Camera / photo capture</td><td>Partial (<code>getUserMedia</code>)</td><td>Native photo picker UX, existing-photo-library access</td><td>Tracked centrally as sovereign epic task 20.6.</td></tr><tr><td>Calendar read/write</td><td>No</td><td>No Web API for OS calendar integration</td><td>Not currently referenced by any specific plugin need in this workspace; candidate only, not requested by a consumer yet.</td></tr><tr><td>NFC</td><td>No</td><td>No Web API equivalent; iOS NFC access is especially restrictive</td><td>Candidate only; no consumer identified yet. Requires investigating iOS Core NFC entitlement and session-lifetime constraints before scoping.</td></tr><tr><td>Biometric auth (Face ID / fingerprint)</td><td>No</td><td>Local device unlock gate, not a Sovereign auth mechanism</td><td>Tracked centrally as sovereign epic task 20.7. Does not replace or duplicate instance-side auth — see <a href="./../adrs/0003-cookie-in-webview-auth.html">ADR 0003</a>.</td></tr><tr><td>Background location / background work</td><td>No</td><td>Requires background execution entitlements on both platforms</td><td>Explicitly called out in RFC 0058 as needing its own capability RFC — highest-scrutiny candidate on this list.</td></tr><tr><td>Push notifications (APNs/FCM)</td><td>Partial (Web Push)</td><td>Reliability and delivery-when-app-closed guarantees</td><td>Tracked centrally as sovereign epic task 20.5; deferred out of the first store release per workstream 0002.</td></tr></tbody></table><h2 id="how-a-candidate-graduates-off-this-list" tabindex="-1">How a candidate graduates off this list <a class="header-anchor" href="#how-a-candidate-graduates-off-this-list" aria-label="Permalink to &quot;How a candidate graduates off this list&quot;">​</a></h2><ol><li>A concrete plugin need is identified (not speculative — an actual plugin blocked without it).</li><li>The capability is added to sovereign RFC 0083&#39;s registry (protocol change happens in <code>sovereign</code>, not here — see <a href="./../adrs/0004-shared-device-bridge-contract-with-desktop.html">ADR 0004</a>).</li><li>Permission string, privacy declaration, and consent UX are defined before any implementation starts.</li><li>An epic task is created in <a href="./../epics/bridge.html">docs/epics/bridge.md</a> and this row is updated to point at it.</li></ol><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li>Should calendar and NFC be scoped now, speculatively, or left off the registry until a specific plugin asks for them? Current lean: leave them off — RFC 0083&#39;s stated strategy is additive-as-needed, not front-loaded.</li><li>Does background location need a dedicated RFC before it&#39;s even a candidate here, given RFC 0058 already flags it as needing one?</li></ul>',11)])])}const b=t(o,[["render",n]]);export{u as __pageData,b as default};
